<script setup lang="ts">
import {ref,watch} from 'vue';
import {useManagedChart} from '../../../charts/useManagedChart';
import {use,type EChartsCoreOption} from 'echarts/core';import {GraphChart} from 'echarts/charts';import {TooltipComponent} from 'echarts/components';import {CanvasRenderer} from 'echarts/renderers';
import type {LeakSuspect} from '../../../types/leak';
import {pipeColors,type PipelineNetwork,type PipelineType} from '../../../types/pipeline';
use([GraphChart,TooltipComponent,CanvasRenderer]);
const props=defineProps<{network:PipelineNetwork;types:PipelineType[];selected:string;trace:string[];suspects?:LeakSuspect[];previewValves?:string[];closedValves?:string[];isolatedEdges?:string[]}>();const emit=defineEmits<{'edge':[id:string];'node':[id:string]}>();
const host=ref<HTMLElement>();
function option():EChartsCoreOption{const edges=props.network.edges.filter(e=>props.types.includes(e.pipelineType));const ids=new Set(edges.flatMap(e=>[e.startNodeId,e.endNodeId]));return {tooltip:{trigger:'item'},series:[{type:'graph',layout:'none',roam:true,edgeSymbol:['none','arrow'],edgeSymbolSize:7,label:{show:true,color:'#b7cedb',fontSize:10,position:'right'},data:props.network.nodes.filter(n=>ids.has(n.id)).map(n=>({id:n.id,name:n.name,x:n.x*5+(n.metadata.pipelineType==='water'?-600:n.metadata.pipelineType==='fire'?600:0),y:n.z*5,symbol:n.nodeType==='valve'?'diamond':n.buildingId?'rect':'circle',symbolSize:n.nodeType==='valve'?14:10,itemStyle:{color:props.closedValves?.some(id=>props.network.valves.find(v=>v.id===id)?.nodeId===n.id)?'#65747f':props.previewValves?.some(id=>props.network.valves.find(v=>v.id===id)?.nodeId===n.id)?'#ffe18a':pipeColors[n.metadata.pipelineType]}})),links:edges.map(e=>({id:e.id,name:e.id,source:e.startNodeId,target:e.endNodeId,lineStyle:{color:props.isolatedEdges?.includes(e.id)?'#65747f':props.trace.includes(e.id)?'#ffba68':(props.suspects?.findIndex(s=>s.pipeline_id===e.id)??-1)>=0?['#ee716c','#e9a455','#e4d879'][props.suspects!.findIndex(s=>s.pipeline_id===e.id)]:pipeColors[e.pipelineType],width:e.id===props.selected?5:props.trace.includes(e.id)?3:1.5,opacity:.85},label:{show:e.id===props.selected,formatter:e.id,color:'#fff'}}))}]};}
const {error,render,retry,getChart}=useManagedChart(host,option,chart=>{chart.on('click',(event)=>{const data=event.data as {id?:string};if(data.id){if(event.dataType==='edge')emit('edge',data.id);else emit('node',data.id);}});if(import.meta.env.DEV&&host.value)Object.defineProperty(host.value,'__topologyDebug',{configurable:true,get:()=>{
 const rect=host.value!.getBoundingClientRect();const nodes=props.network.nodes.filter(n=>props.types.includes(n.metadata.pipelineType)).map(n=>{const point=getChart()!.convertToPixel({seriesIndex:0},[n.x*5+(n.metadata.pipelineType==='water'?-600:n.metadata.pipelineType==='fire'?600:0),n.z*5]) as number[];return {id:n.id,x:rect.left+point[0]!,y:rect.top+point[1]!};});
 return {closedValves:props.closedValves,isolatedEdges:props.isolatedEdges,suspects:props.suspects,previewValves:props.previewValves,selected:props.selected,trace:props.trace,nodes,edges:props.network.edges.filter(e=>props.types.includes(e.pipelineType)).map(e=>{const a=nodes.find(n=>n.id===e.startNodeId)!,b=nodes.find(n=>n.id===e.endNodeId)!;return {id:e.id,x:(a.x+b.x)/2,y:(a.y+b.y)/2};})};}});
});
watch(()=>[props.network,props.types,props.selected,props.trace,props.suspects,props.previewValves,props.closedValves,props.isolatedEdges],()=>render(),{deep:true});
</script><template><section class="panel topology-panel"><h3>二维管网拓扑 <small>箭头为设计方向 · 菱形为阀门 · 点击联动三维</small></h3><div class="managed-chart"><div ref="host" data-testid="pipeline-topology" class="topology-chart"></div><div v-if="error" class="chart-error" role="status"><span>{{error}}</span><button type="button" @click="retry">重新加载图表</button></div></div></section></template>
